<?php

$operation = array( 'operation_id' => 'op-1', 'kind' => 'create', 'started_at' => '2026-09-21 15:04:00', 'base_version' => 1, 'provider' => 'zoom', 'owner_id' => 42, 'provider_id' => null, 'dispatch_state' => 'not_dispatched', 'course_id' => 7, 'topic_id' => 8, 'post_author' => 42, 'menu_order' => 3, 'title' => 'Live', 'content' => 'Notes', 'start_local' => '2026-09-21 15:04:00', 'end_local' => '2026-09-21 16:04:00', 'timezone' => 'UTC', 'duration' => array( 'value' => 60, 'unit' => 'minutes' ), 'provider_target' => array( 'auto_recording' => 'none', 'enforce_login' => false, 'host_id' => 'host-1', 'host_video' => false, 'join_before_host' => true, 'mute_upon_entry' => false, 'participant_video' => false, 'waiting_room' => true ), 'delete_hook' => null );
$envelope  = array( 'schema_version' => 1, 'version' => 1, 'state' => 'pending', 'provider' => 'zoom', 'owner_id' => 42, 'provider_id' => null, 'provenance' => null, 'error' => null, 'warning' => null, 'reconciliation_required' => false, 'operation' => $operation );
$stored    = TutorPress_Live_Lesson_Sync_Envelope::envelope( $envelope );
tutorpress_live_lessons_assert( is_array( $stored ) && 42 === $stored['operation']['owner_id'] && is_int( $stored['operation']['owner_id'] ) && 'op-1' === $stored['operation']['operation_id'] && 'host-1' === $stored['operation']['provider_target']['host_id'], 'common snapshot keeps the owner user id, operation id, and zoom host id' );
$headers = $envelope;
$headers['operation']['headers'] = array( 'Cookie' => 'a=b' );
$token = $envelope;
$token['operation']['refresh_token'] = 'x';
$raw = $envelope;
$raw['operation']['raw_response'] = 'body';
tutorpress_live_lessons_assert( null === TutorPress_Live_Lesson_Sync_Envelope::envelope( $headers ) && null === TutorPress_Live_Lesson_Sync_Envelope::envelope( $token ) && null === TutorPress_Live_Lesson_Sync_Envelope::envelope( $raw ), 'snapshot excludes request headers, tokens, and raw responses' );
$google = array_merge( $operation, array( 'provider' => 'google_meet', 'duration' => array( 'value' => 9, 'unit' => 'hours' ), 'provider_target' => array( 'add_enrolled_students' => 'No', 'reminder_minutes' => 10, 'send_updates' => 'all', 'transparency' => 'opaque', 'visibility' => 'default', 'status' => 'confirmed' ) ) );
tutorpress_live_lessons_assert( is_array( TutorPress_Live_Lesson_Sync_Envelope::envelope( array_merge( $envelope, array( 'provider' => 'google_meet', 'operation' => $google ) ) ) ), 'google meet keeps scalar settings and a duration above the zoom cap' );
tutorpress_live_lessons_assert( null === TutorPress_Live_Lesson_Sync_Envelope::envelope( array_merge( $envelope, array( 'operation' => array_merge( $operation, array( 'duration' => array( 'value' => 9, 'unit' => 'hours' ) ) ) ) ) ) && null === TutorPress_Live_Lesson_Sync_Envelope::envelope( array_merge( $envelope, array( 'operation' => array_merge( $operation, array( 'start_local' => '2026-09-21 15:04:30' ) ) ) ) ) && null === TutorPress_Live_Lesson_Sync_Envelope::envelope( array_merge( $envelope, array( 'operation' => array_merge( $operation, array( 'timezone' => 'Mars/Base' ) ) ) ) ) && null === TutorPress_Live_Lesson_Sync_Envelope::envelope( array_merge( $envelope, array( 'operation' => array_merge( $operation, array( 'delete_hook' => array( 'lesson_id' => 9, 'title' => 'Live', 'topic_id' => 8, 'type' => 'zoom' ) ) ) ) ) ) && null === TutorPress_Live_Lesson_Sync_Envelope::envelope( array_merge( $envelope, array( 'operation' => array_merge( $operation, array( 'kind' => 'delete' ) ) ) ) ) && null === TutorPress_Live_Lesson_Sync_Envelope::envelope( array_merge( $envelope, array( 'provider' => 'google_meet', 'operation' => array_merge( $google, array( 'provider_target' => array_merge( $google['provider_target'], array( 'attendees' => array( array( 'email' => 'student@example.com' ) ) ) ) ) ) ) ) ), 'zoom cap, wall clock, timezone, delete-hook, and attendee rules reject' );
$delete = array_merge( $operation, array( 'kind' => 'delete', 'delete_hook' => array( 'lesson_id' => 9, 'title' => 'Live', 'topic_id' => 8, 'type' => 'zoom' ) ) );
$deleted = TutorPress_Live_Lesson_Sync_Envelope::envelope( array_merge( $envelope, array( 'operation' => $delete ) ) );
tutorpress_live_lessons_assert( is_array( $deleted ) && 9 === $deleted['operation']['delete_hook']['lesson_id'] && 'zoom' === $deleted['operation']['delete_hook']['type'], 'delete keeps only the sanitized hook snapshot' );
tutorpress_live_lessons_pass( 'schedule, provider, and delete snapshots' );
$interrupted        = array_replace( $envelope, array( 'state' => 'pending' ) );
$interrupted_stored = TutorPress_Live_Lesson_Sync_Envelope::envelope( $interrupted );
tutorpress_live_lessons_assert( is_array( $interrupted_stored ) && 'pending' === $interrupted_stored['state'] && is_array( $interrupted_stored['operation'] ) && 'op-1' === $interrupted_stored['operation']['operation_id'] && null === $interrupted_stored['provider_id'] && null === $interrupted_stored['operation']['provider_id'], 'an interrupted create stays stored with its operation and no provider id' );
$abandoned   = array_replace( $envelope, array( 'state' => 'error', 'provider_id' => null, 'operation' => null, 'reconciliation_required' => false, 'version' => 2 ) );
$abandonment = TutorPress_Live_Lesson_Sync_Envelope::envelope( $abandoned );
tutorpress_live_lessons_assert( is_array( $abandonment ) && 'error' === $abandonment['state'] && null === $abandonment['operation'] && null === $abandonment['provider_id'] && false === $abandonment['reconciliation_required'] && 'synced' !== $abandonment['state'] && 'unlinked' !== $abandonment['state'], 'abandonment stays an error envelope with no operation and no provider id' );
tutorpress_live_lessons_assert( null === TutorPress_Live_Lesson_Sync_Envelope::identity_request( array( 'operation_id' => 'op-1', 'provider_id' => null, 'version' => 1 ) ) && 'not_dispatched' === $interrupted_stored['operation']['dispatch_state'] && null === $interrupted_stored['provider_id'], 'an id-less uncertain create is not retried' );
$attach = TutorPress_Live_Lesson_Sync_Envelope::identity_request( array( 'operation_id' => 'op-1', 'provider_id' => 'evt-9', 'version' => 1 ) );
tutorpress_live_lessons_assert( is_array( $attach ) && 'evt-9' === $attach['provider_id'] && null === $interrupted_stored['provider_id'] && null === $interrupted_stored['operation']['provider_id'], 'an attach input does not write its provider id onto the stored envelope' );
$stale = TutorPress_Live_Lesson_Sync_Envelope::envelope( array_replace( $envelope, array( 'operation' => array_merge( $operation, array( 'operation_id' => 'op-2' ) ) ) ) );
tutorpress_live_lessons_assert( is_array( $stale ) && 'op-2' === $stale['operation']['operation_id'] && TutorPress_Live_Lesson_Sync_Envelope::canonical_bytes( $interrupted_stored ) !== TutorPress_Live_Lesson_Sync_Envelope::canonical_bytes( $stale ), 'a different operation id is a different canonical envelope' );
tutorpress_live_lessons_pass( 'interruption, abandonment, stale operation, and attach mismatch' );
